/**
 * Operator-flow eval: do the panel's buttons agree with the real backend?
 *
 * Reads ../contract/state-matrix.json, which the Python backend generated by
 * driving GameController into every phase. Run: node services/web/evals/flows.mjs
 *
 * - sound: a control the UI enables is one the backend accepts (no 409 clicks).
 * - complete: with the projector open, every control the backend accepts is
 *   enabled, so the operator is never stuck behind a disabled button.
 * - no_camera: without a live camera, nothing that needs a frame is enabled.
 * - journey: the moves an operator needs are enabled where they need them.
 * - reopen: every phase with the projector closed recovers after J.
 * - guidance: whenever every panel button is disabled, the panel names what
 *   unblocks it (camera, J for the projector, or the cross in the projector
 *   window), never points at a disabled button, and the backend message
 *   cannot hide a browser-side blocker.
 * - lights: on real /api/preview responses, the start, goal and corner
 *   lights are all "on" exactly when a scan of the same frame succeeds.
 * - camera: in five simulated rooms (contract/camera-trials.json, frames
 *   scored by the real backend), the fixed-camera search picks a setting
 *   the scan accepts, without clipping, with white balance within 1000 K of
 *   the light and exposure within 2x of the ideal.
 * - camera_choice: every order in which the FaceTime camera, the iPhone, its
 *   Desk View and the C920 can appear (with or without an operator pick, a scan between
 *   arrivals) ends on the wall-facing camera (C920, else iPhone) when nothing
 *   was picked or scanned, never leaves a picked camera and never hops
 *   after a scan (that would discard the board).
 * - projector_theme: in the dark and light projector backgrounds a scan
 *   still sees pure black, and every stroke keeps its contrast (4:1, the
 *   faint grid 2.5:1) against its background.
 */

import { readFileSync } from "node:fs";
import { pathToFileURL } from "node:url";

import {
  bestTrial, cameraToSwitchTo, contrastRatio, controlsFor, presetScore, PROJECTOR_THEMES, projectorBackground,
  roleLights, SCAN_BLACK, searchPlan, setupGuide, statusText,
} from "../ui/ui-core.mjs";

const matrix = JSON.parse(readFileSync(new URL("../contract/state-matrix.json", import.meta.url), "utf8"));
const previews = JSON.parse(readFileSync(new URL("../contract/preview-samples.json", import.meta.url), "utf8"));
const cameraTrials = JSON.parse(readFileSync(new URL("../contract/camera-trials.json", import.meta.url), "utf8"));
const c920 = JSON.parse(readFileSync(new URL("../contract/c920-capabilities.json", import.meta.url), "utf8"));
const CONTROLS = ["scan", "launch", "aim", "reset", "resume"];
const NEEDS_CAMERA = ["scan", "launch"];
const JOURNEY = [
  ["waiting_camera", "scan"],
  ["partial_live", "scan"],
  ["no_markers", "launch"],
  ["ready", "aim"],
  ["ready", "launch"],
  ["running", "reset"],
  ["won", "reset"],
  ["won", "scan"],
  ["lost", "reset"],
  ["paused_open", "resume"],
  ["paused_open", "scan"],

];
const REOPEN = { projector_closed: "waiting_camera", ready_closed: "ready", paused_closed: "paused_open" };

function uiControls(state, cameraReady = true) {
  return controlsFor(state, cameraReady, Boolean(state.projection.open));
}

function phaseCase(name, { state, accepts }) {
  const ui = uiControls(state);
  const noCamera = uiControls(state, false);
  const unsound = CONTROLS.filter((c) => ui[c] && !accepts[c]);
  const missing = state.projection.open ? CONTROLS.filter((c) => accepts[c] && !ui[c]) : [];
  const cameraLeak = NEEDS_CAMERA.filter((c) => noCamera[c]);
  return {
    case: `phase:${name}`,
    passed: unsound.length + missing.length + cameraLeak.length === 0,
    ui_enabled: CONTROLS.filter((c) => ui[c]),
    backend_accepts: CONTROLS.filter((c) => accepts[c]),
    unsound,
    missing,
    camera_leak: cameraLeak,
  };
}

function journeyCase() {
  const blocked = JOURNEY
    .filter(([phase, control]) => {
      const { state, accepts } = matrix.phases[phase];
      return !(uiControls(state)[control] && accepts[control]);
    })
    .map(([phase, control]) => `${phase}:${control}`);
  return { case: "journey", passed: blocked.length === 0, steps: JOURNEY.length, blocked };
}

function reopenCase() {
  const stuck = Object.entries(REOPEN)
    .filter(([closed, open]) => {
      const before = matrix.phases[closed].state;
      const after = matrix.phases[open].state;
      const sameAttempt = before.game.status === after.game.status && before.game.paused === after.game.paused;
      const anyEnabled = CONTROLS.some((c) => uiControls(after)[c]);
      return before.projection.open || !after.projection.open || !sameAttempt || !anyEnabled;
    })
    .map(([closed]) => closed);
  return { case: "reopen", passed: stuck.length === 0, stuck };
}

const OUTSIDE_PANEL = new Set(["camera", "projector", "detect"]);
const NAMES_ITS_FIX = { camera: /cámara/i, projector: /\bJ\b/, detect: /inicio.*llegada/i };

function guidanceCase() {
  const seen = new Set();
  const unguided = [];
  let deadStates = 0;
  for (const [name, { state }] of Object.entries(matrix.phases)) {
    for (const camera of [true, false]) {
      for (const popup of [true, false]) {
        const ready = popup && Boolean(state.projection.open);
        const key = `${name}|camera=${camera}|projector=${ready}`;
        if (seen.has(key)) continue;
        seen.add(key);
        const controls = controlsFor(state, camera, ready);
        const guide = setupGuide(state, camera, ready);
        const dead = CONTROLS.every((c) => !controls[c]);
        deadStates += dead;
        const problems = [];
        if (dead && !OUTSIDE_PANEL.has(guide.step)) problems.push(`dead state guides to ${guide.step}`);
        if (NAMES_ITS_FIX[guide.step] && !NAMES_ITS_FIX[guide.step].test(guide.message)) problems.push("message lacks the fix");
        if (["scan"].includes(guide.step) && !controls[guide.step]) problems.push(`points at disabled ${guide.step}`);
        if (guide.blocking && statusText(null, state, guide) !== guide.message) problems.push("backend message hides blocker");
        if (problems.length) unguided.push({ state: key, problems });
      }
    }
  }
  return { case: "guidance", passed: unguided.length === 0, combos: seen.size, dead_states: deadStates, unguided };
}

function lightsCase() {
  const wrong = Object.entries(previews.samples)
    .map(([name, sample]) => {
      const lights = roleLights(sample.preview);
      const ready = ["start", "goal"].every((role) => lights[role].state === "on");
      return { sample: name, lights_ready: ready, scan_ok: sample.scan_ok };
    })
    .filter((row) => row.lights_ready !== row.scan_ok);
  return { case: "lights", passed: wrong.length === 0, samples: Object.keys(previews.samples).length, wrong };
}

function cameraCase() {
  const plan = searchPlan(c920);
  const sameGrid = JSON.stringify([plan.exposureTime, plan.colorTemperature])
    === JSON.stringify([cameraTrials.grid.exposureTime, cameraTrials.grid.colorTemperature]);
  const rooms = cameraTrials.rooms.map((room) => {
    const best = bestTrial(room.trials.map((trial) => ({ ...trial, score: presetScore(trial.preview) })));
    const { quality } = best.preview;
    const { exposureTime, colorTemperature } = best.settings;
    const passed = quality.ready && quality.clipped < 0.02
      && Math.abs(colorTemperature - room.light_k) <= 1000
      && exposureTime >= room.ideal_exposure / 2 && exposureTime <= room.ideal_exposure * 2;
    return { room: room.name, light_k: room.light_k, ideal_exposure: room.ideal_exposure,
      chosen: best.settings, ready: quality.ready, clipped: quality.clipped, passed };
  });
  return { case: "camera", passed: sameGrid && rooms.every((room) => room.passed), same_grid: sameGrid, rooms };
}

const DEVICES = {
  facetime: { kind: "videoinput", deviceId: "f", label: "Cámara FaceTime HD" },
  desk: { kind: "videoinput", deviceId: "d", label: "Cámara de Vista del Escritorio de iPhone de Tobias" },
  phone: { kind: "videoinput", deviceId: "p", label: "Cámara de iPhone de Tobias" },
  c920: { kind: "videoinput", deviceId: "b", label: "HD Pro Webcam C920 (046d:082d)" },
};
const WALL_ORDER = ["c920", "phone", "facetime", "desk"];

function orders(items) {
  if (items.length <= 1) return [items];
  return items.flatMap((item, i) => orders([...items.slice(0, i), ...items.slice(i + 1)]).map((rest) => [item, ...rest]));
}

// Replays the page: the first device to arrive starts (startCamera prefers
// the same way), every later arrival is a devicechange.
function cameraChoiceCase() {
  const problems = [];
  let runs = 0;
  for (const arrival of orders(Object.keys(DEVICES))) {
    for (const picked of ["", ...Object.keys(DEVICES)]) {
      for (const scanAfter of [null, 0, 1]) {
        runs += 1;
        const remembered = picked ? DEVICES[picked].label : "";
        const present = [];
        let active = "";
        let scanned = false;
        const run = `${arrival.join(">")} pick=${picked || "-"} scan=${scanAfter ?? "-"}`;
        arrival.forEach((name, step) => {
          present.push(DEVICES[name]);
          const target = cameraToSwitchTo({ devices: present, activeId: active, remembered, scanned });
          if (target && scanned) problems.push(`${run}: cambió de cámara después de escanear`);
          if (target && picked && active === DEVICES[picked].deviceId) problems.push(`${run}: dejó la cámara elegida`);
          if (target) active = target;
          if (step === scanAfter) scanned = true;
        });
        const want = picked ? DEVICES[picked].deviceId
          : DEVICES[WALL_ORDER.find((name) => present.includes(DEVICES[name]))].deviceId;
        if (!scanned && active !== want) problems.push(`${run}: terminó en ${active}, esperaba ${want}`);
      }
    }
  }
  return { case: "camera_choice", passed: problems.length === 0, runs, problems };
}

function themeCase() {
  const problems = [];
  for (const [theme, colors] of Object.entries(PROJECTOR_THEMES)) {
    if (projectorBackground(theme, true) !== SCAN_BLACK) problems.push(`${theme}: el escaneo no ve negro`);
    for (const [name, color] of Object.entries(colors)) {
      if (name === "background") continue;
      const minimum = name === "grid" ? 2.5 : 4;
      const ratio = contrastRatio(color, colors.background);
      if (ratio < minimum) problems.push(`${theme}.${name} contraste ${ratio.toFixed(2)} < ${minimum}`);
    }
  }
  return { case: "projector_theme", passed: problems.length === 0, themes: Object.keys(PROJECTOR_THEMES), problems };
}

export function runEval() {
  const guidance = guidanceCase();
  const cases = [
    ...Object.entries(matrix.phases).map(([name, row]) => phaseCase(name, row)),
    journeyCase(),
    reopenCase(),
    guidance,
    lightsCase(),
    cameraCase(),
    cameraChoiceCase(),
    themeCase(),
  ];
  const passed = cases.filter((c) => c.passed).length;
  return {
    score: Number((passed / cases.length).toFixed(3)),
    pass_threshold: 1.0,
    disagreements: cases.reduce((n, c) => n + (c.unsound?.length ?? 0) + (c.missing?.length ?? 0), 0),
    dead_states: guidance.dead_states,
    unguided_states: guidance.unguided.length,
    cases,
  };
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const report = runEval();
  console.log(JSON.stringify(report, null, 2));
  process.exitCode = report.score >= report.pass_threshold ? 0 : 1;
}
